#define main retained_management_catalog_main
#include "linux_management_catalog_tests.cpp"
#undef main

namespace {
app::AlphaConfigurationSnapshot settings(rt::LinuxRuntimeHost& runtime){const auto value=app::decode_configuration_snapshot(exchange(runtime,app::LocalControlMessageType::configuration_snapshot_request,{},app::LocalControlMessageType::configuration_snapshot_response));check(value.has_value(),"typed saved and active settings decode");return *value;}
app::AlphaConfigurationUpdateRequest edit(rt::LinuxRuntimeHost& runtime){const auto current=settings(runtime);auto candidate=current.saved;candidate.configuration_revision++;return {current.saved.configuration_revision,std::move(candidate)};}
app::AlphaConfigurationUpdateResult save(rt::LinuxRuntimeHost& runtime,const app::AlphaConfigurationUpdateRequest& request){const auto result=app::decode_configuration_update_result(exchange(runtime,app::LocalControlMessageType::configuration_update_request,app::encode_configuration_update_request(request),app::LocalControlMessageType::configuration_update_response));check(result.has_value(),"typed save result decodes");return *result;}
host::FileDescriptor reserve(std::uint16_t& port){host::FileDescriptor fd(socket(AF_INET,SOCK_STREAM|SOCK_CLOEXEC,0));sockaddr_in address{};address.sin_family=AF_INET;address.sin_addr.s_addr=htonl(INADDR_LOOPBACK);check(fd&&bind(fd.get(),reinterpret_cast<sockaddr*>(&address),sizeof(address))==0&&listen(fd.get(),2)==0,"reserve isolated test port");socklen_t length=sizeof(address);check(getsockname(fd.get(),reinterpret_cast<sockaddr*>(&address),&length)==0,"read reserved port");port=ntohs(address.sin_port);return fd;}
}
int main(int argc,char** argv){try{
    check(argc==3&&geteuid()!=0,"isolated board/timezone under normal account");check(host::LinuxBbsTimeZoneRuleProvider::initialize(argv[2]),"time rules initialized");Clock clock;rt::LinuxRuntimeHost runtime(argv[1],clock,[]{return false;});check(runtime.open().code==app::LocalControlResponseCode::ok&&runtime.start_bbs().code==app::LocalControlResponseCode::ok,"actual Runtime starts BBS");
    auto caller=std::make_unique<Client>(runtime.status().telnet_port);const auto original=await_callers(runtime,1);const auto identity=original.nodes.front().screen_owner;
    auto name=edit(runtime);name.configuration.bbs_name="Live native board";const auto named=save(runtime,name);check(named.code==app::LocalControlResponseCode::ok&&named.activation==app::AlphaConfigurationActivation::applied,"ordinary live settings applied");
    check(settings(runtime).active.bbs_name=="Live native board"&&await_callers(runtime,1).nodes.front().screen_owner==identity,"live save preserves exact connected caller assignment");
    check(save(runtime,name).code==app::LocalControlResponseCode::invalid_request,"stale configuration CAS refused");
    std::uint16_t busy_port{};auto blocker=reserve(busy_port);auto endpoint=edit(runtime);endpoint.configuration.telnet.port=busy_port;const auto refused=save(runtime,endpoint);check(refused.code!=app::LocalControlResponseCode::ok&&settings(runtime).saved.configuration_revision==endpoint.expected_revision,"failed candidate binding cannot save settings");check(await_callers(runtime,1).nodes.front().screen_owner==identity,"failed binding preserves caller");
    blocker=host::FileDescriptor{};const auto changed=save(runtime,endpoint);check(changed.code==app::LocalControlResponseCode::ok&&runtime.status().telnet_port==busy_port,"single endpoint swaps while caller remains");auto second=std::make_unique<Client>(busy_port);check(await_callers(runtime,2).nodes.front().screen_owner==identity,"old and new endpoint callers coexist");
    auto combined=edit(runtime);combined.configuration.telnet.port=static_cast<std::uint16_t>(busy_port==65535?65534:busy_port+1);combined.configuration.ssh.enabled=true;const auto combined_result=save(runtime,combined);check(combined_result.code!=app::LocalControlResponseCode::ok&&settings(runtime).saved.configuration_revision==combined.expected_revision,"combined endpoint change with callers refuses without saving");
    auto hostname=edit(runtime);hostname.configuration.hostname_lookup=!hostname.configuration.hostname_lookup;const auto pending=save(runtime,hostname);check(pending.code==app::LocalControlResponseCode::ok&&pending.activation==app::AlphaConfigurationActivation::pending_safe_boundary,"hostname boundary saves pending with callers");check(settings(runtime).active.hostname_lookup!=settings(runtime).saved.hostname_lookup,"pending saved and active snapshots remain distinct");
    second.reset();caller.reset();(void)await_callers(runtime,0);const auto applied=settings(runtime);check(applied.activation==app::AlphaConfigurationActivation::applied&&applied.active.hostname_lookup==applied.saved.hostname_lookup&&applied.active.configuration_revision==hostname.configuration.configuration_revision,"pending settings apply at actual zero-caller boundary");
    check(applied.active.hostname_lookup,"controlled fixture enables hostname lookup at boundary");auto named_caller=std::make_unique<Client>(runtime.status().telnet_port);(void)await_callers(runtime,1);bool resolved{};
    for(unsigned attempt=0;attempt<300;++attempt){const auto status=wire_status(runtime);if(!status.nodes.empty()&&status.nodes.front().hostname=="display.example"){resolved=true;break;}std::this_thread::sleep_for(std::chrono::milliseconds(10));}
    check(resolved,"actual Runtime caller publishes normalized display-only hostname through typed status");auto disable_lookup=edit(runtime);disable_lookup.configuration.hostname_lookup=false;check(save(runtime,disable_lookup).activation==app::AlphaConfigurationActivation::pending_safe_boundary,"disable lookup waits for current hostname caller");named_caller.reset();(void)await_callers(runtime,0);check(!settings(runtime).active.hostname_lookup,"lookup disabled at safe boundary");
    auto zone=edit(runtime);zone.configuration.bbs_time_zone=zone.configuration.bbs_time_zone=="UTC"?"Pacific Standard Time":"UTC";const auto rezoned=save(runtime,zone);check(rezoned.code==app::LocalControlResponseCode::ok&&settings(runtime).active.bbs_time_zone==zone.configuration.bbs_time_zone&&runtime.status().scheduler.configuration_loaded,"timezone save recomputes native scheduler with active settings");
    auto restart=edit(runtime);restart.configuration.logical_nodes=restart.configuration.logical_nodes==3?4:3;const auto saved=save(runtime,restart);check(saved.code==app::LocalControlResponseCode::ok&&saved.activation==app::AlphaConfigurationActivation::restart_required,"node count saved with explicit restart requirement");const auto separated=settings(runtime);check(separated.active.logical_nodes!=separated.saved.logical_nodes&&runtime.status().lifecycle.configured_nodes==separated.active.logical_nodes,"runtime status retains actual active node count");
    check(runtime.stop_bbs().response.code==app::LocalControlResponseCode::ok&&runtime.start_bbs().code==app::LocalControlResponseCode::ok,"normal restart applies saved settings");check(settings(runtime).active.logical_nodes==restart.configuration.logical_nodes&&settings(runtime).activation==app::AlphaConfigurationActivation::applied,"restarted active state matches durable node count");
    check(runtime.shutdown().code==app::LocalControlResponseCode::ok,"all callers and workers joined on shutdown");check(runtime.open().code==app::LocalControlResponseCode::ok&&!runtime.bbs_owned()&&settings(runtime).saved.logical_nodes==restart.configuration.logical_nodes,"reopen is stopped with durable final settings");check(runtime.shutdown().code==app::LocalControlResponseCode::ok,"reopened management closes");
    std::cout<<"PASS "<<checks<<" actual typed native live settings and retained caller checks\n";return 0;
}catch(const std::exception& error){std::cerr<<"FAIL "<<checks<<": "<<error.what()<<'\n';return 1;}}
